mapper.insert:
INSERT INTO special_holidays (
    business_id, holiday_date, reason
) VALUES (
             #{businessId}, #{holidayDate}, #{reason}
         )

mapper.select:
SELECT * FROM special_holidays
WHERE business_id = #{businessId}
ORDER BY holiday_date ASC

SELECT * FROM special_holidays
WHERE business_id = #{businessId}
  AND holiday_date BETWEEN #{startDate} AND #{endDate}
ORDER BY holiday_date ASC

SELECT * FROM special_holidays
WHERE business_id = #{businessId}
  AND holiday_date = #{holidayDate}

mapper.delete:
DELETE FROM special_holidays
WHERE business_id = #{businessId}
  AND holiday_date = #{holidayDate}

mapper.select:
SELECT EXISTS(
    SELECT 1 FROM special_holidays WHERE id = #{id}
)

SELECT EXISTS(
    SELECT 1 FROM special_holidays
    WHERE business_id = #{businessId}
      AND holiday_date = #{holidayDate}
)

SELECT EXISTS(
    SELECT 1 FROM special_holidays
    WHERE business_id = #{businessId} AND id = #{id}
)
